<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {ArrowLeft,ArrowRight,Compass,BookOpen,Check,UserRound,Plus,SlidersHorizontal,LoaderCircle,Archive} from 'lucide-vue-next'
import {worldApi} from './api'
import AuthorStartFields from '../authoring/AuthorStartFields.vue'
import type {Opening} from '../authoring/types'
import WorldLookLibrary from '../components/WorldLookLibrary.vue'
import {worldTaskFinished,worldTaskRecovering} from './task-state'
import {newKey,authGeneration} from '../api'
import {worldMutation,pendingWorldMutation,clearWorldMutation} from './mutation-intent'
import type {Anchor} from '../api/types'
import {defaultRules} from './types'
import type {WorldInfo,WorldTask,WorldSource,WorldTemplate} from './types'
import {useRequestScope} from '../platform/request-scope'
const route=useRoute(),router=useRouter(),capture=useRequestScope(),sources=ref<WorldSource[]>([]),bookId=ref(String(route.query.book||'')),branchId=ref(''),chapterIndex=ref(-1),sourceAnchor=ref<Anchor|null>(null),rules=ref(defaultRules()),world=ref<WorldInfo|null>(null),name=ref(''),character=ref(''),customName=ref(''),identity=ref(''),opening=ref(''),fullReference=ref(false),advanced=ref(false),busy=ref(false),stopping=ref(false),loading=ref(true),error=ref(''),task=ref<WorldTask|null>(null)
const lookPreviews=ref<Record<string,string>>({})
const sourceKind=ref<'book'|'standalone'>('book'),templates=ref<WorldTemplate[]>([]),templateId=ref(''),templatesLoading=ref(false),templateError=ref('')
const creationReceipt=ref<{worldId:string;taskId:string|null}|null>(null)
const selectedTemplate=computed(()=>templates.value.find(t=>t.id===templateId.value)),canCreate=computed(()=>sourceKind.value==='book'?!!sourceAnchor.value:!!selectedTemplate.value)
const book=computed(()=>sources.value.find(b=>b.id===bookId.value)),branches=computed(()=>book.value?.lines||[]),branch=computed(()=>branches.value.find(l=>l.id===branchId.value)),characters=computed(()=>world.value?.characters||[]),archived=computed(()=>world.value?.status==='archived'),prepared=computed(()=>world.value?.status==='active'&&(!task.value||worldTaskFinished(task.value))),recovering=computed(()=>worldTaskRecovering(task.value)),step=computed(()=>world.value?prepared.value?3:2:1)
const useSuggestedModel=ref(true)
const openingId=ref(String(route.query.opening||'')),playerValues=ref<Record<string,string|number|boolean|string[]|null>>({})
function chooseAuthorOpening(selected:Opening){if(selected.characterId)character.value=selected.characterId;opening.value=selected.text}
let timer:ReturnType<typeof setTimeout>|undefined,observation=0
function selectBook(){branchId.value=branches.value[0]?.id||'';selectBranch()}
function selectBranch(){chapterIndex.value=-1;sourceAnchor.value=branch.value?.anchor||null}
function selectChapter(){sourceAnchor.value=chapterIndex.value<0?branch.value?.anchor||null:branch.value?.chapters[chapterIndex.value]?.anchor||null}
async function loadTemplates(){if(templatesLoading.value)return;const scope=capture();templatesLoading.value=true;templateError.value='';try{const result=await worldApi<{items:WorldTemplate[]}>('/templates');if(!scope.valid())return;templates.value=result.items;templateId.value=result.items.some(t=>t.id===templateId.value)?templateId.value:result.items[0]?.id||'';if(rules.value.genre==='general'&&selectedTemplate.value)rules.value.genre=selectedTemplate.value.genre}catch(e){if(scope.valid())templateError.value=(e as Error).message}finally{if(scope.valid())templatesLoading.value=false}}
function selectSource(kind:'book'|'standalone'){if(busy.value||world.value||creationReceipt.value)return;sourceKind.value=kind;error.value='';if(kind==='standalone'&&!templates.value.length)void loadTemplates()}
function chooseTemplate(id:string){if(busy.value||creationReceipt.value)return;const template=templates.value.find(t=>t.id===id);if(!template)return;templateId.value=id;rules.value.genre=template.genre}
function stopPreparationObservation(){observation++;clearTimeout(timer);timer=undefined;busy.value=false;stopping.value=false;error.value=''}
function observePreparation(id:string){if(archived.value){stopPreparationObservation();return}clearTimeout(timer);const version=++observation,scope=capture();task.value=null;busy.value=true;stopping.value=false;void poll(id,scope,version)}
async function poll(id:string,scope:ReturnType<typeof capture>,version:number){const valid=()=>version===observation&&scope.valid();if(!valid())return;try{const result=await worldApi<WorldTask>('/tasks/'+id);if(!valid())return;task.value=result;const info=await worldApi<WorldInfo>('/worlds/'+(result.result.worldId||world.value?.id));if(!valid())return;world.value=info;if(info.status==='archived'){stopPreparationObservation();return}if(info.status==='active'&&result.state==='succeeded'&&worldTaskFinished(result)){if(!character.value)character.value=world.value?.recommendedCharacterId||characters.value.find(c=>c.available)?.id||'custom';busy.value=false;return}if(worldTaskFinished(result)&&result.state!=='succeeded'){busy.value=false;error.value=result.state==='cancelled'?'已停止准备。':result.errorCode==='PROVIDER_STATUS_UNKNOWN'?'模型响应暂时无法确认，这次请求已保留。':'准备未完成，可以重新准备。';return}timer=setTimeout(()=>void poll(id,scope,version),1200)}catch(e){if(valid()){error.value=(e as Error).message;timer=setTimeout(()=>void poll(id,scope,version),2500)}}}
async function cancelPreparation(){const current=task.value;if(archived.value||!current||worldTaskFinished(current)||stopping.value)return;const scope=capture(),version=observation;stopping.value=true;try{await worldApi('/tasks/'+current.id+'/cancel',{method:'POST',body:{}})}catch(e){if(scope.valid()&&version===observation)error.value=(e as Error).message}finally{if(scope.valid()&&version===observation)stopping.value=false}}
async function restoreCreation(scope:ReturnType<typeof capture>){
  const pending=await pendingWorldMutation('create');if(!scope.valid()||!pending)return
  const body=pending.body as {templateId?:string;anchor?:Anchor;fullBookReference?:boolean;name:string;rules:ReturnType<typeof defaultRules>}
  name.value=body.name;rules.value=body.rules;fullReference.value=!!body.fullBookReference
  if(body.templateId){sourceKind.value='standalone';await loadTemplates();if(!scope.valid())return;templateId.value=body.templateId}
  else if(body.anchor){sourceKind.value='book';bookId.value=body.anchor.bookId;branchId.value=body.anchor.branchId;sourceAnchor.value=body.anchor}
  error.value='上次创建的响应尚未确认，点击建立世界可恢复同一次操作。'
}
async function restoreBegin(scope:ReturnType<typeof capture>){
  if(!world.value)return;const pending=await pendingWorldMutation('begin:'+world.value.id);if(!scope.valid()||!pending)return
  const body=pending.body as {characterId:string|null;customName:string;customIdentity:string;opening:string;openingId?:string;playerValues?:Record<string,string|number|boolean|string[]|null>}
  character.value=body.characterId||'custom';customName.value=body.customName;identity.value=body.customIdentity;opening.value=body.opening;openingId.value=body.openingId||'';playerValues.value=body.playerValues||{}
  error.value='上次进入的响应尚未确认，点击进入故事可恢复同一次操作。'
}
async function create(){if((!canCreate.value&&!creationReceipt.value)||busy.value)return;const scope=capture();busy.value=true;error.value='';const source=sourceKind.value==='standalone'?{templateId:templateId.value}:{anchor:sourceAnchor.value,fullBookReference:fullReference.value,maxCalls:8};try{const result=creationReceipt.value||await worldMutation<{worldId:string;taskId:string|null}>('create','/worlds',{...source,name:name.value,rules:rules.value},scope.valid);if(!scope.valid())return;creationReceipt.value=result;const info=await worldApi<WorldInfo>('/worlds/'+result.worldId);if(!scope.valid())return;world.value=info;if(world.value?.opening&&!opening.value)opening.value=world.value.opening;await restoreBegin(scope);if(!scope.valid())return;if(result.taskId)observePreparation(result.taskId);else{if(!character.value)character.value=world.value?.recommendedCharacterId||characters.value.find(c=>c.available)?.id||'custom';busy.value=false}}catch(e){if(scope.valid()){error.value=(e as Error).message;busy.value=false}}}
async function retry(){if(!world.value||archived.value||busy.value)return;const scope=capture();busy.value=true;error.value='';try{const result=await worldApi<{taskId:string}>('/worlds/'+world.value.id+'/prepare',{method:'POST',key:newKey(),body:{}});if(scope.valid())observePreparation(result.taskId)}catch(e){if(scope.valid()){error.value=(e as Error).message;busy.value=false}}}
async function begin(){if(!world.value||archived.value||busy.value)return;const scope=capture(),auth=authGeneration(),worldId=world.value.id;busy.value=true;error.value='';try{const result=await worldMutation<{lineId:string}>('begin:'+worldId,'/worlds/'+worldId+'/begin',{openingId:openingId.value||null,playerValues:playerValues.value,useSuggestedModel:useSuggestedModel.value,characterId:character.value==='custom'?null:character.value,customName:customName.value,customIdentity:identity.value,opening:opening.value,lineName:character.value==='custom'?customName.value+'的故事':(characters.value.find(c=>c.id===character.value)?.name||'我')+'的故事'},scope.valid);if(scope.valid()&&!archived.value){await router.push(`/worlds/${worldId}/play?line=${result.lineId}`);await clearWorldMutation('begin:'+worldId,()=>authGeneration()===auth);await clearWorldMutation('create',()=>authGeneration()===auth,worldId)}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
onMounted(async()=>{const scope=capture();try{if(route.query.world){const info=await worldApi<WorldInfo>('/worlds/'+route.query.world);if(!scope.valid())return;world.value=info;character.value=info.recommendedCharacterId||info.characters?.find(c=>c.available)?.id||'custom';if(info.prepareTaskId&&info.status!=='archived')observePreparation(info.prepareTaskId);if(world.value?.opening&&!opening.value)opening.value=world.value.opening;await restoreBegin(scope)}else{const result=await worldApi<{items:WorldSource[]}>('/sources');if(!scope.valid())return;sources.value=result.items;bookId.value=bookId.value||result.items[0]?.id||'';selectBook();if(route.query.branch){branchId.value=String(route.query.branch);selectBranch()}if(route.query.anchor){try{sourceAnchor.value=JSON.parse(String(route.query.anchor))}catch{error.value='起点无法读取，请重新选择'}}if(!route.query.book&&!result.items.some(b=>b.lines.length)){sourceKind.value='standalone';await loadTemplates()}await restoreCreation(scope)}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())loading.value=false}})
onUnmounted(()=>{observation++;clearTimeout(timer)})
</script>
<template><div class="world-create"><div class="world-create-title"><span class="world-emblem"><Compass :size="28"/></span><h1>走进一个故事</h1><div class="world-steps"><span :class="{active:step===1,done:step>1}">01 起点</span><i></i><span :class="{active:step===2,done:step>2}">02 世界</span><i></i><span :class="{active:step===3}">03 身份</span></div></div><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="loading" class="loading">正在打开来源…</div><section v-else-if="archived" class="world-create-card world-preparing" aria-label="已归档世界"><div class="world-preparing-orbit"><Archive :size="38"/></div><h2>{{world?.name}}</h2><p role="status">这个世界已归档。</p><p class="hint">请回到世界列表恢复后再继续。</p><RouterLink to="/worlds" class="inline-link">回到世界列表</RouterLink></section><form v-else-if="step===1" class="world-create-card" @submit.prevent="create">
<div class="world-source-tabs" role="group" aria-label="故事起点"><button type="button" :aria-pressed="sourceKind==='book'" :disabled="busy||!!creationReceipt" @click="selectSource('book')"><BookOpen :size="17"/>从小说开始</button><button type="button" :aria-pressed="sourceKind==='standalone'" :disabled="busy||!!creationReceipt" @click="selectSource('standalone')"><Compass :size="17"/>建立新故事</button></div>
<div v-if="sourceKind==='standalone'" class="world-template-picker"><div v-if="templatesLoading" class="loading" role="status">正在打开故事…</div><template v-else-if="templateError"><p class="error" role="alert">{{templateError}}</p><button type="button" @click="loadTemplates">重新载入</button></template><div v-else class="world-template-grid" role="group" aria-label="选择一个起点"><button v-for="t in templates" :key="t.id" type="button" class="world-template" :class="{selected:templateId===t.id}" :aria-pressed="templateId===t.id" :disabled="busy||!!creationReceipt" @click="chooseTemplate(t.id)"><span class="world-template-mark"><Compass :size="23"/></span><small>{{({mystery:'悬疑',fantasy:'武侠',romance:'人物情感'} as Record<string,string>)[t.genre]||'故事'}}</small><strong>{{t.title}}</strong><span>{{t.description}}</span><Check v-if="templateId===t.id" :size="17" class="world-template-check"/></button></div></div>
<template v-else><label><BookOpen :size="16"/>选择小说<select v-model="bookId" @change="selectBook"><option v-if="!sources.length" value="">先到书架打开一本小说</option><option v-for="b in sources" :key="b.id" :value="b.id">{{b.title}}</option></select></label><label v-if="branches.length>1">故事线<select v-model="branchId" @change="selectBranch"><option v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>从哪里开始<select v-if="branch" v-model="chapterIndex" @change="selectChapter"><option :value="-1">当前已读位置</option><option v-for="(c,i) in branch.chapters" :key="c.anchor.blockId" :value="i">{{c.title}} · 已读结尾</option></select><span v-else class="muted">先阅读一个段落，就能从那里进入。</span></label></template><label>世界名称<input v-model="name" :readonly="busy||!!creationReceipt" :placeholder="(sourceKind==='book'?book?.title:selectedTemplate?.title)||'给世界起个名字（选填）'" maxlength="160"></label><button type="button" class="world-disclosure" :aria-expanded="advanced" @click="advanced=!advanced"><SlidersHorizontal :size="17"/>世界规则<span>{{advanced?'−':'+'}}</span></button><div v-if="advanced" class="world-advanced"><div class="world-form-columns"><label>故事类型<select v-model="rules.genre"><option value="general">跟随原作</option><option value="mystery">悬疑调查</option><option value="romance">人物情感</option><option value="fantasy">武侠与奇幻</option><option value="political">势力与权谋</option><option value="survival">生存探索</option></select></label><label>叙事节奏<select v-model="rules.pace"><option value="short">简短</option><option value="standard">标准</option><option value="detailed">细腻</option></select></label></div><label>死亡规则<select v-model="rules.deathPolicy"><option value="end">故事在死亡后结束</option><option value="rescue">可以等待救援</option><option value="rebirth">允许有代价的重生</option></select></label><label class="world-check"><input v-model="rules.relationshipNumbers" type="checkbox">使用数字关系</label><label class="world-check"><input v-model="rules.randomChecks" type="checkbox">启用随机行动判定</label><label v-if="sourceKind==='book'" class="world-check"><input v-model="fullReference" type="checkbox">导演可以参考全书设定<span>未来情节只作参考</span></label><label>写作风格<input v-model="rules.style" maxlength="500" placeholder="选填"></label><label>补充规则<textarea v-model="rules.customRules" maxlength="1500" placeholder="选填"></textarea></label></div><button class="primary world-full-button" :disabled="busy||!canCreate">{{busy?'正在打开…':creationReceipt?'打开已创建的世界':'建立世界'}}<ArrowRight :size="18"/></button></form><section v-else-if="step===2" class="world-create-card world-preparing"><div class="world-preparing-orbit"><LoaderCircle v-if="busy" :size="38" class="world-spin"/><Compass v-else :size="38"/></div><h2>{{world?.name}}</h2><p role="status">{{busy?recovering?'正在恢复保存…':'正在整理眼前的人与事…':'这次准备还未完成'}}</p><small v-if="busy&&task?.result.preparationBatches">{{task.result.preparedBatches||0}} / {{task.result.preparationBatches}}</small><button v-if="busy&&task&&!worldTaskFinished(task)" type="button" class="world-full-button" :disabled="stopping" @click="cancelPreparation">{{stopping?'正在停止…':'停止准备'}}</button><button v-if="!busy" class="primary" @click="retry">重新准备</button><RouterLink to="/worlds" class="inline-link">回到世界列表</RouterLink></section><form v-else class="world-create-card" @submit.prevent="begin"><p class="world-opening">{{world?.description}}</p><div v-if="world?.authoring?.suggestedModel" class="product-hint"><p>作者建议：{{world.authoring.suggestedModel}}。只有你有权使用的通道才能生效；不可用时使用账号默认模型。</p><label><input type="checkbox" v-model="useSuggestedModel">优先使用可用的建议模型（取消则始终跟随账号默认）</label></div><AuthorStartFields v-if="world?.authoring" :config="world.authoring" v-model:opening-id="openingId" v-model:values="playerValues" @choose="chooseAuthorOpening"/><h2>你想成为谁？</h2><RouterLink v-if="world" :to="'/worlds/'+world.id+'/author'" class="inline-link">作者配置与公开发布</RouterLink><WorldLookLibrary v-if="world" :world-id="world.id" :disabled="busy" @previews="lookPreviews=$event"/><div class="world-identity-grid"><button v-for="c in characters" :key="c.id" type="button" class="world-identity" :class="{selected:character===c.id}" :disabled="!c.available" @click="character=c.id"><span class="world-avatar"><img v-if="lookPreviews[c.id]" :src="lookPreviews[c.id]" :alt="c.name+'头像'" style="width:100%;height:100%;object-fit:cover;border-radius:50%"><template v-else>{{c.name.slice(0,1)}}</template></span><strong>{{c.name}}</strong><span>{{c.available?c.description:'当前时点不可扮演'}}</span><Check v-if="character===c.id" :size="17" class="world-identity-check"/></button><button type="button" class="world-identity" :class="{selected:character==='custom'}" @click="character='custom'"><span class="world-avatar"><Plus :size="23"/></span><strong>一个新人物</strong><span>用自己的身份进入</span><Check v-if="character==='custom'" :size="17" class="world-identity-check"/></button></div><template v-if="character==='custom'"><label><UserRound :size="16"/>你的名字<input v-model="customName" required maxlength="80"></label><label>一句话身份<textarea v-model="identity" required maxlength="800" placeholder="例如：路过渡口的药师，正在寻找一位旧友"></textarea></label></template><label>你想怎样开场？<textarea v-model="opening" maxlength="1200" placeholder="选填，让故事自然开始也很好"></textarea></label><button class="primary world-full-button" :disabled="busy||!character||character==='custom'&&(!customName.trim()||!identity.trim())">{{busy?'正在进入…':'进入故事'}}<ArrowRight :size="18"/></button></form></div></template>
